sp_widget.client_script:
api.controller = function($window) {

  var c = this;

  var KEY = 'gn.reviewerRail.tight';

  /* =========================================================
     COLLAPSE / EXPAND STATE
     ========================================================= */

  function remembered() {
    try {
      return $window.sessionStorage.getItem(KEY) === '1';
    } catch (e) {
      return false;
    }
  }

  function remember(v) {
    try {
      $window.sessionStorage.setItem(KEY, v ? '1' : '0');
    } catch (e) {
      /* Storage may be unavailable. */
    }
  }

  c.tight = remembered();

  c.toggle = function() {
    c.tight = !c.tight;
    remember(c.tight);
  };


  /* =========================================================
     NAVIGATION
     ========================================================= */

  function configureNavigation() {

    if (!c.data || !c.data.groups) {
      return;
    }

    angular.forEach(c.data.groups, function(group) {

      if (!group || !group.items) {
        return;
      }

      angular.forEach(group.items, function(item) {

        if (!item) {
          return;
        }

        /*
         * Reviewer Rail → Programs
         *
         * Always open the applicant portal's
         * Opportunities page.
         */
        if (item.label === 'Programs') {
          item.url = '/applicant?id=opportunities';
        }

      });

    });

  }

  configureNavigation();

};

sp_widget.css:
/* =========================================================
   GATENOW · REVIEWER RAIL
   Service Portal widget · CSS / SCSS
   ========================================================= */


/* =========================================================
   DESIGN TOKENS
   ========================================================= */

$gn-card:        #ffffff;
$gn-line:        #e7eaf2;
$gn-line-soft:   #eff2f7;

$gn-ink:         #16203a;
$gn-ink-2:       #3f4a63;
$gn-muted:       #7b8598;
$gn-muted-2:     #9aa3b4;

$gn-indigo:      #4457c9;
$gn-indigo-dk:   #3a4bb3;
$gn-indigo-soft: #aebcf5;
$gn-indigo-wash: #edf1ff;

$gn-red:         #e0525f;
$gn-red-wash:    #fdecee;
$gn-red-line:    #f6d3d7;

$gn-font: "Poppins", "Inter", "Segoe UI",
          -apple-system, BlinkMacSystemFont,
          Arial, sans-serif;

$gnr-wide:  252px;
$gnr-tight: 72px;


/* =========================================================
   FRAME
   ========================================================= */

.panel,
.panel-body,
.sp-widget {

  overflow: visible !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;

}


.gnr {

  width: $gnr-wide;
  height: 100%;

  font-family: $gn-font;

  transition: width 0.4s ease;

}


.gnr.is-tight {

  width: $gnr-tight;

}


.gnr *,
.gnr *::before,
.gnr *::after {

  box-sizing: border-box;

}


/* =========================================================
   INNER RAIL
   ========================================================= */

.gnr__inner {

  display: flex;

  flex-direction: column;

  width: 100%;
  height: 100%;

  min-height: 100vh;

  background: $gn-card;

  border-right: 1px solid $gn-line;

  overflow: visible;

}


/* =========================================================
   BRAND
   ========================================================= */

.gnr__brand {

  position: relative;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  height: 68px;

  padding: 0 16px;

  border-bottom: 1px solid $gn-line-soft;

  flex-shrink: 0;

}


/* =========================================================
   BRAND LINK
   ========================================================= */

.gnr-mark {

  display: flex;

  align-items: center;

  gap: 12px;

  min-width: 0;

  color: $gn-ink;

  text-decoration: none;

}


.gnr-mark:hover,
.gnr-mark:focus {

  color: $gn-ink;

  text-decoration: none;

}


/* =========================================================
   GATENOW LOGO CONTAINER
   ========================================================= */

.gnr-mark__glyph {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: 10px;
  background: $gn-card;
  box-shadow: 0 6px 14px rgba(68, 87, 201, 0.22);
  overflow: hidden;
  transition: transform 0.35s ease;
}


/* =========================================================
   GATENOW LOGO IMAGE
   ========================================================= */

.gnr-mark__logo {
  display: block;
  width: 26px;
  height: 26px;
  object-fit: contain;
  border-radius: 0;
}


.gnr-mark:hover .gnr-mark__glyph {

  transform: scale(1.04);

}


/* =========================================================
   BRAND TEXT
   ========================================================= */

.gnr-mark__text {

  display: flex;

  flex-direction: column;

  gap: 1px;

  min-width: 0;

  white-space: nowrap;

  overflow: hidden;

  transition: opacity 0.28s ease;

}


.gnr-mark__name {

  font-size: 18px;

  font-weight: 600;

  letter-spacing: -0.4px;

  line-height: 1.2;

  color: $gn-ink;

}


.gnr-mark__sub {

  font-size: 10.5px;

  font-weight: 600;

  letter-spacing: 0.8px;

  text-transform: uppercase;

  color: $gn-muted-2;

}


/* =========================================================
   COLLAPSE BUTTON
   ========================================================= */

/* sits on the rail's right edge, half in and half out, in
   both states, like the applicant sidebar's toggle */
.gnr-pull {

  position: absolute;

  top: 50%;

  right: -13px;

  margin-top: -13px;

  z-index: 2;

  display: flex;

  align-items: center;

  justify-content: center;

  width: 26px;

  height: 26px;

  flex-shrink: 0;

  padding: 0;

  border: 1px solid $gn-line;

  border-radius: 50%;

  background: $gn-card;

  color: $gn-muted;

  cursor: pointer;

  box-shadow: 0 2px 8px rgba(22, 32, 58, 0.1);

  transition:
    background 0.25s ease,
    color 0.25s ease,
    border-color 0.25s ease,
    transform 0.4s ease;

}


.gnr-pull:hover {

  background: $gn-indigo-wash;

  border-color: $gn-indigo-soft;

  color: $gn-indigo;

}


/* rotate only the arrow: rotating the whole button also flips its "Expand" tooltip */
.gnr.is-tight .gnr-pull svg {

  transform: rotate(180deg);

}


/* =========================================================
   NAVIGATION
   ========================================================= */

.gnr__scroll {

  flex: 1;

  min-height: 0;

  padding: 16px 12px 10px;

  overflow: visible;

}


.gnr-group {

  margin-bottom: 22px;

}


.gnr .gnr-group__label {

  margin: 0 0 8px;

  padding: 0 10px;

  font-size: 11.5px;

  font-weight: 600;

  letter-spacing: 0.8px;

  text-transform: uppercase;

  color: $gn-muted;

  white-space: nowrap;

  overflow: hidden;

  transition: opacity 0.28s ease;

}


.gnr .gnr-group__list {

  display: grid;

  gap: 2px;

  margin: 0;

  padding: 0;

  list-style: none;

}


/* =========================================================
   NAV ITEM
   ========================================================= */

.gnr-item {

  position: relative;

  display: flex;

  align-items: center;

  gap: 12px;

  height: 42px;

  padding: 0 12px;

  border-radius: 10px;

  color: $gn-ink-2;

  font-size: 14px;

  font-weight: 500;

  text-decoration: none;

  white-space: nowrap;

  transition:
    background 0.22s ease,
    color 0.22s ease;

}


.gnr-item:hover,
.gnr-item:focus {

  background: #f7f9fc;

  color: $gn-ink;

  text-decoration: none;

}


/* =========================================================
   ACTIVE ITEM
   ========================================================= */

.gnr-item.is-here {

  background: $gn-indigo-wash;

  color: $gn-indigo;

  font-weight: 600;

}


.gnr-item.is-here:hover,
.gnr-item.is-here:focus {

  background: #e4eaff;

  color: $gn-indigo-dk;

}


/* =========================================================
   ACTIVE EDGE
   ========================================================= */

.gnr-item__edge {

  position: absolute;

  top: 50%;

  left: 0;

  width: 3px;

  height: 0;

  border-radius: 0 3px 3px 0;

  background: $gn-indigo;

  transform: translateY(-50%);

  transition: height 0.28s ease;

}


.gnr-item.is-here .gnr-item__edge {

  height: 20px;

}


/* =========================================================
   NAV ICON
   ========================================================= */

.gnr-item__ico {

  display: flex;

  align-items: center;

  justify-content: center;

  width: 20px;

  flex-shrink: 0;

  color: $gn-muted;

  transition: color 0.22s ease;

}


.gnr-item:hover .gnr-item__ico {

  color: $gn-ink-2;

}


.gnr-item.is-here .gnr-item__ico {

  color: $gn-indigo;

}


/* =========================================================
   NAV LABEL
   ========================================================= */

.gnr-item__label {

  flex: 1;

  min-width: 0;

  overflow: hidden;

  text-overflow: ellipsis;

}


/* =========================================================
   COUNT BADGE
   ========================================================= */

.gnr-item__n {

  flex-shrink: 0;

  min-width: 22px;

  padding: 2px 8px;

  border-radius: 999px;

  background: #f1f3f8;

  color: $gn-ink-2;

  font-size: 11.5px;

  font-weight: 500;

  text-align: center;

  transition:
    background 0.22s ease,
    color 0.22s ease;

}


.gnr-item__n.is-alert {

  background: $gn-red-wash;

  color: #cf4351;

}


.gnr-item.is-here .gnr-item__n {

  background: #ffffff;

  color: $gn-indigo;

}


/* =========================================================
   OVERDUE
   ========================================================= */

.gnr-alert {

  display: flex;

  align-items: center;

  gap: 11px;

  height: 42px;

  margin: 0 12px 12px;

  padding: 0 12px;

  border: 1px solid $gn-red-line;

  border-radius: 10px;

  background: $gn-red-wash;

  color: $gn-ink-2;

  text-decoration: none;

  white-space: nowrap;

  flex-shrink: 0;

  transition:
    background 0.25s ease,
    border-color 0.25s ease;

}


.gnr-alert:hover,
.gnr-alert:focus {

  background: #fbe1e4;

  border-color: #eebcc2;

  color: $gn-ink-2;

  text-decoration: none;

}


.gnr-alert__ico,
.gnr-alert__icon {

  display: flex;

  align-items: center;

  justify-content: center;

  width: 20px;

  flex-shrink: 0;

  color: $gn-red;

}


.gnr-alert__body {

  display: flex;

  flex-direction: column;

  gap: 2px;

  min-width: 0;

  overflow: hidden;

}


.gnr-alert__n {

  font-size: 13px;

  font-weight: 600;

  color: #cf4351;

}


.gnr-alert__sub {

  font-size: 11px;

  color: $gn-muted;

  overflow: hidden;

  text-overflow: ellipsis;

}


/* =========================================================
   FOOTER / USER
   ========================================================= */

.gnr__foot {

  display: flex;

  align-items: center;

  gap: 8px;

  padding: 10px 12px 14px;

  border-top: 1px solid $gn-line-soft;

  flex-shrink: 0;

}


/* =========================================================
   USER LINK
   ========================================================= */

.gnr-me {

  display: flex;

  align-items: center;

  gap: 12px;

  flex: 1;

  min-width: 0;

  padding: 4px;

  margin: -4px;

  border-radius: 10px;

  color: $gn-ink-2;

  text-decoration: none;

  white-space: nowrap;

  transition: background 0.25s ease;

}


.gnr-me:hover,
.gnr-me:focus {

  background: #f7f9fc;

  color: $gn-ink-2;

  text-decoration: none;

}


/* =========================================================
   USER AVATAR
   ========================================================= */

.gnr-me__avatar {

  display: flex;

  align-items: center;

  justify-content: center;

  width: 34px;

  height: 34px;

  flex-shrink: 0;

  border-radius: 10px;

  background: $gn-indigo;

  color: #ffffff;

  font-size: 12.5px;

  font-weight: 600;

  letter-spacing: 0.3px;

}


/* =========================================================
   USER TEXT
   ========================================================= */

.gnr-me__body {

  display: flex;

  flex-direction: column;

  gap: 1px;

  min-width: 0;

  overflow: hidden;

}


.gnr-me__name {

  font-size: 13.5px;

  font-weight: 600;

  letter-spacing: -0.1px;

  color: $gn-ink;

  overflow: hidden;

  text-overflow: ellipsis;

}


.gnr-me__role {

  font-size: 11.5px;

  color: $gn-muted;

  overflow: hidden;

  text-overflow: ellipsis;

}


/* =========================================================
   SIGN OUT
   ========================================================= */

.gnr-out {

  display: flex;

  align-items: center;

  justify-content: center;

  width: 34px;

  height: 34px;

  flex-shrink: 0;

  border-radius: 10px;

  color: $gn-muted-2;

  text-decoration: none;

  transition:
    background 0.25s ease,
    color 0.25s ease;

}


.gnr-out:hover,
.gnr-out:focus {

  background: $gn-red-wash;

  color: #cf4351;

  text-decoration: none;

}


/* =========================================================
   COLLAPSED STATE
   ========================================================= */

.gnr.is-tight .gnr__brand {

  justify-content: center;

  gap: 0;

  padding: 0;

}


/* the template uses __text and __copy, not __body, so those
   are listed too. Sign-out hides in the narrow rail, as it
   does on the applicant sidebar. */
.gnr.is-tight .gnr-mark__text,
.gnr.is-tight .gnr-item__label,
.gnr.is-tight .gnr-item__n,
.gnr.is-tight .gnr-alert__body,
.gnr.is-tight .gnr-alert__text,
.gnr.is-tight .gnr-me__body,
.gnr.is-tight .gnr-me__copy,
.gnr.is-tight .gnr-out {

  /* flex, min-width and padding are zeroed too, otherwise the
     hidden label (flex: 1) and count (min-width: 22px) still
     take up room and push the icon off centre */
  flex: 0 0 0;

  width: 0;

  min-width: 0;

  padding: 0;

  margin: 0;

  opacity: 0;

  overflow: hidden;

  pointer-events: none;

}


.gnr.is-tight .gnr-mark {

  justify-content: center;

}


/* =========================================================
   COLLAPSED SECTION LABEL
   ========================================================= */

.gnr.is-tight .gnr-group__label {

  height: 1px;

  margin: 0 6px 12px;

  padding: 0;

  overflow: hidden;

  background: $gn-line-soft;

  color: transparent;

}


/* =========================================================
   COLLAPSED NAV ITEMS
   ========================================================= */

.gnr.is-tight .gnr-item,
.gnr.is-tight .gnr-me {

  justify-content: center;

  gap: 0;

  padding: 0;

}


.gnr.is-tight .gnr-alert {

  justify-content: center;

  gap: 0;

  padding: 0;

}


.gnr.is-tight .gnr__foot {

  justify-content: center;

  gap: 0;

  padding: 10px 0 14px;

}


.gnr.is-tight .gnr-me {

  flex: 0 0 auto;

  margin: 0;

}


/* =========================================================
   COLLAPSED BADGE DOT
   ========================================================= */

.gnr.is-tight .gnr-item__ico {

  position: relative;

}


.gnr.is-tight .gnr-item.has-n .gnr-item__ico::after,
.gnr.is-tight .gnr-item.has-alert .gnr-item__ico::after {

  content: "";

  position: absolute;

  top: -1px;

  right: -4px;

  width: 7px;

  height: 7px;

  border-radius: 50%;

  box-shadow: 0 0 0 2px $gn-card;

}


.gnr.is-tight .gnr-item.has-n .gnr-item__ico::after {

  background: $gn-indigo;

}


.gnr.is-tight .gnr-item.has-alert .gnr-item__ico::after {

  background: $gn-red;

}


.gnr.is-tight .gnr-item.is-here .gnr-item__ico::after {

  box-shadow: 0 0 0 2px $gn-indigo-wash;

}


/* =========================================================
   TOOLTIPS
   ========================================================= */

/* .gnr-pull is left out on purpose: it is absolutely
   positioned above, and listing it here overrode that and
   pushed it outside the rail. */
.gnr.is-tight .gnr-item,
.gnr.is-tight .gnr-alert,
.gnr.is-tight .gnr-me,
.gnr.is-tight .gnr-out {

  position: relative;

}


.gnr.is-tight [data-tip]::before {

  content: attr(data-tip);

  position: absolute;

  top: 50%;

  left: calc(100% + 12px);

  z-index: 60;

  padding: 8px 11px;

  border-radius: 9px;

  background: $gn-ink;

  color: #ffffff;

  font-size: 11.5px;

  font-weight: 500;

  white-space: nowrap;

  opacity: 0;

  transform:
    translate(-5px, -50%);

  pointer-events: none;

  transition:
    opacity 0.18s ease,
    transform 0.18s ease;

}


.gnr.is-tight [data-tip]:hover::before,
.gnr.is-tight [data-tip]:focus-visible::before {

  opacity: 1;

  transform:
    translate(0, -50%);

}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

.gnr-item:focus-visible,
.gnr-me:focus-visible,
.gnr-out:focus-visible,
.gnr-mark:focus-visible,
.gnr-alert:focus-visible,
.gnr-pull:focus-visible {

  outline: 2px solid $gn-indigo;

  outline-offset: -2px;

}


/* =========================================================
   ENTRY ANIMATION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gnrIn {

    from {

      opacity: 0;

      transform: translateX(-8px);

    }

    to {

      opacity: 1;

      transform: translateX(0);

    }

  }


  .gnr__brand {

    animation:
      gnrIn 0.4s ease backwards;

  }


  .gnr .gnr-group__label {

    animation:
      gnrIn 0.36s ease 0.06s backwards;

  }


  .gnr .gnr-group__list li {

    animation:
      gnrIn 0.36s ease backwards;

  }


  .gnr .gnr-group__list li:nth-child(1) {

    animation-delay: 0.08s;

  }


  .gnr .gnr-group__list li:nth-child(2) {

    animation-delay: 0.12s;

  }


  .gnr .gnr-group__list li:nth-child(3) {

    animation-delay: 0.16s;

  }


  .gnr .gnr-group__list li:nth-child(n+4) {

    animation-delay: 0.20s;

  }


  .gnr-alert {

    animation:
      gnrIn 0.38s ease 0.24s backwards;

  }


  .gnr__foot {

    animation:
      gnrIn 0.38s ease 0.28s backwards;

  }

}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {

  .gnr,
  .gnr.is-tight {

    width: $gnr-tight;

  }


  .gnr .gnr-mark__text,
  .gnr .gnr-item__label,
  .gnr .gnr-item__n,
  .gnr .gnr-alert__body,
  .gnr .gnr-alert__text,
  .gnr .gnr-me__body,
  .gnr .gnr-me__copy,
  .gnr .gnr-out {

    flex: 0 0 0;

    width: 0;

    min-width: 0;

    padding: 0;

    margin: 0;

    opacity: 0;

    overflow: hidden;

    pointer-events: none;

  }


  .gnr .gnr-group__label {

    height: 1px;

    margin: 0 6px 12px;

    padding: 0;

    overflow: hidden;

    background: $gn-line-soft;

    color: transparent;

  }


  .gnr .gnr__brand {

    justify-content: center;

    gap: 0;

    padding: 0;

  }


  .gnr .gnr-mark {

    justify-content: center;

  }


  .gnr .gnr-pull {

    display: none;

  }


  .gnr .gnr__scroll {

    padding-top: 16px;

  }


  .gnr .gnr-item,
  .gnr .gnr-me {

    justify-content: center;

    gap: 0;

    padding: 0;

  }


  .gnr .gnr-alert {

    justify-content: center;

    gap: 0;

    padding: 0;

  }


  .gnr .gnr__foot {

    justify-content: center;

    gap: 0;

    padding: 10px 0 14px;

  }


  .gnr .gnr-me {

    flex: 0 0 auto;

    margin: 0;

  }


  .gnr .gnr-item__ico {

    position: relative;

  }


  .gnr .gnr-item.has-n .gnr-item__ico::after,
  .gnr .gnr-item.has-alert .gnr-item__ico::after {

    content: "";

    position: absolute;

    top: -1px;

    right: -4px;

    width: 7px;

    height: 7px;

    border-radius: 50%;

    box-shadow: 0 0 0 2px $gn-card;

  }


  .gnr .gnr-item.has-n .gnr-item__ico::after {

    background: $gn-indigo;

  }


  .gnr .gnr-item.has-alert .gnr-item__ico::after {

    background: $gn-red;

  }


  .gnr .gnr-item.is-here .gnr-item__ico::after {

    box-shadow:
      0 0 0 2px $gn-indigo-wash;

  }


  .gnr-item,
  .gnr-alert,
  .gnr-me,
  .gnr-out {

    position: relative;

  }


  .gnr [data-tip]::before {

    content: attr(data-tip);

    position: absolute;

    top: 50%;

    left: calc(100% + 12px);

    z-index: 60;

    padding: 8px 11px;

    border-radius: 9px;

    background: $gn-ink;

    color: #ffffff;

    font-size: 11.5px;

    font-weight: 500;

    white-space: nowrap;

    opacity: 0;

    transform:
      translate(-5px, -50%);

    pointer-events: none;

    transition:
      opacity 0.18s ease,
      transform 0.18s ease;

  }


  .gnr [data-tip]:hover::before,
  .gnr [data-tip]:focus-visible::before {

    opacity: 1;

    transform:
      translate(0, -50%);

  }

}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .gnr,
  .gnr * {

    transition: none;

    animation: none;

  }


  .gnr-mark:hover .gnr-mark__glyph {

    transform: none;

  }

}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · REVIEWER RAIL
     Service Portal widget · Server script

     Navigation for the reviewer portal, plus the two counts
     worth carrying on it: how much is open, and how much of
     that is late.

     ── ITS OWN WIDGET ────────────────────────────────────────

     The rail is separate from the dashboard that embeds it. A
     rail built inside a dashboard means the dashboard owns
     navigation for pages it knows nothing about, and adding a
     page means editing a widget with no other reason to
     change. Here every reviewer page drops in the same widget
     and the menu is defined once.

     ── THE COUNTS ────────────────────────────────────────────

     GlideAggregate, not a walk of the table. The rail renders
     on every page and must not cost a full read of the review
     table each time one loads.

     The two counts are scoped differently on purpose. "Open"
     uses the reviewer field, the list of groups a review is
     assigned to, so it means open across every panel this
     person sits on. "Overdue" uses review_group, the panel
     that currently holds it, because a review running late in
     somebody else's queue is not theirs to chase.
     ========================================================= */


  var REVIEW = 'x_enno_gatenow_grant_review';

  var DONE     = 'Review completed';
  var DECLINED = 'Declined by Reviewer';

  var me = gs.getUserID();


  /* ============================================================
     OPTIONS
     ============================================================ */

  function opt(name, fallback) {

    var v = options[name];

    return (v === null || v === undefined || v === '')
      ? fallback
      : v.toString();

  }


  /* ============================================================
     URL HELPER
     ============================================================ */

  function url(pageId) {

    return '?id=' + pageId;

  }


  /* ============================================================
     WHO
     ============================================================ */

  var u = gs.getUser();

  data.user = {

    name:
      u.getDisplayName() ||
      gs.getUserName(),

    title: '',

    initials:
      (
        (u.getFirstName() || 'R').charAt(0) +
        (u.getLastName()  || '').charAt(0)
      ).toUpperCase()

  };


  try {

    var ur =
      new GlideRecordSecure('sys_user');

    if (ur.get(me)) {

      data.user.title =
        ur.getValue('title') || '';

    }

  } catch (e) {

    /* The job title is decoration, not a requirement. */

  }


  /* ============================================================
     THE COUNTS
     ============================================================ */

  var groups = [];

  try {

    var gm =
      new GlideRecordSecure('sys_user_grmember');

    gm.addQuery('user', me);
    gm.query();

    while (gm.next()) {

      groups.push(
        gm.getValue('group')
      );

    }

  } catch (e) {

    gs.warn(
      '[ReviewerRail] group membership unreadable: ' +
      e.message
    );

  }


  data.hasGroups =
    groups.length > 0;


  var open    = 0;
  var overdue = 0;


  if (groups.length) {


    /* ==========================================================
       DETERMINE REVIEWER FIELD
       ========================================================== */

    var useReviewer = false;

    try {

      var probe =
        new GlideRecordSecure(REVIEW);

      useReviewer =
        probe.isValid() &&
        probe.isValidField('reviewer');

    } catch (e) {

      /* Fall back to review_group below. */

    }


    /* ==========================================================
       OPEN REVIEWS
       ========================================================== */

    try {

      var ga =
        new GlideAggregate(REVIEW);


      /*
       * reviewer is a list of groups, so the match is CONTAINS
       * per group, OR'd on the QueryCondition.
       */

      if (useReviewer) {

        var qc =
          ga.addQuery(
            'reviewer',
            'CONTAINS',
            groups[0]
          );


        for (
          var i = 1;
          i < groups.length;
          i++
        ) {

          qc.addOrCondition(
            'reviewer',
            'CONTAINS',
            groups[i]
          );

        }

      } else {

        ga.addQuery(
          'review_group',
          'IN',
          groups.join(',')
        );

      }


      ga.addQuery( 'status', 'Review in progress' ); /* matches the Applicants to review list */

      ga.addAggregate('COUNT');

      ga.query();


      if (ga.next()) {

        open =
          parseInt(
            ga.getAggregate('COUNT'),
            10
          ) || 0;

      }

    } catch (e) {

      gs.info(
        '[ReviewerRail] open count unavailable: ' +
        e.message
      );

    }


    /* ==========================================================
       OVERDUE REVIEWS
       ========================================================== */

    try {

      var gd =
        new GlideAggregate(REVIEW);


      gd.addQuery(
        'review_group',
        'IN',
        groups.join(',')
      );

      gd.addQuery( 'status', 'Review in progress' ); /* matches the Applicants to review list */

      gd.addQuery(
        'review_deadline',
        '<',
        new GlideDateTime().getValue()
      );

      gd.addAggregate('COUNT');

      gd.query();


      if (gd.next()) {

        overdue =
          parseInt(
            gd.getAggregate('COUNT'),
            10
          ) || 0;

      }

    } catch (e) {

      gs.info(
        '[ReviewerRail] overdue count unavailable: ' +
        e.message
      );

    }

  }


  data.overdue = overdue;


  /* ============================================================
     CURRENT PAGE
     ============================================================ */

  var here =
    '' +
    ($sp.getParameter('id') || '');


  /* ============================================================
     PAGE CONFIGURATION
     ============================================================ */

  var pages = {

    overview:
      opt(
        'review',
        'review_home_page'
      ),

    queue:
      opt(
        'queue_page',
        'review_applicants'
      ),

    completed:
      opt(
        'completed_page',
        'completed_reviews'
      ),

    programs:
      opt(
        'programs_page',
        'review_programs'
      ),

    profile:
      opt(
        'profile_page',
        'user_profile'
      )

  };


  /* ============================================================
     STANDARD REVIEWER URLS
     ============================================================ */

  data.homeUrl =
    url(pages.overview);

  data.queueUrl =
    url(pages.queue);

  data.profileUrl =
    url(pages.profile);


  /* ============================================================
     LOGOUT URL

     Same architecture as the working GateNow Applicant
     Sidebar.

     The authentication logout is handled by ServiceNow:

       /logout.do

     sysparm_goto_url tells ServiceNow where to go after
     logout.

     The current portal is detected dynamically instead of
     hardcoding /review.
     ============================================================ */

  var portalSuffix = '';

  try {

    portalSuffix =
      $sp.getPortalRecord().getValue('url_suffix') || '';

  } catch (e) {

    gs.info(
      '[ReviewerRail] Unable to determine portal suffix: ' +
      e.message
    );

  }


  /*
   * If the user is currently on a page such as:
   *
   * /review?id=review_applicants
   *
   * then after logout the redirect will return to that page.
   *
   * If there is no page id, return to the reviewer home page.
   */

  var redirectPage =
    here
      ? here
      : pages.overview;


  /*
   * Build the same type of logout URL used by the
   * working GateNow Sidebar.
   */

  if (portalSuffix) {

    data.logoutUrl =
      '/logout.do?sysparm_goto_url=/' +
      portalSuffix +
      '?id=' +
      redirectPage;

  } else {

    /*
     * Fallback in case the portal record cannot be read.
     */

    data.logoutUrl =
      '/logout.do?sysparm_goto_url=/review?id=' +
      redirectPage;

  }


  /* ============================================================
     MENU

     Page ids come from widget options so the rail can be
     repointed without editing a script.

     The current page is read from the URL rather than passed
     in, so any page the rail is dropped on highlights itself
     with no extra wiring.
     ============================================================ */

  data.groups = [

    {
      key  : 'review',
      label: 'Review',

      items: [

        {
          key: 'overview',

          label: 'Overview',

          icon: 'grid',

          url:
            url(pages.overview),

          active:
            here === pages.overview,

          count: 0
        },


        {
          key: 'queue',

          label: 'My reviews',

          icon: 'list',

          url:
            url(pages.queue),

          active:
            here === pages.queue,

          /*
           * The badge carries what is open, and overdue turns
           * it red rather than adding a second badge.
           */

          count:
            open,

          alert:
            overdue > 0
        },


        {
          key: 'completed',

          label: 'Completed',

          icon: 'check',

          url:
            url(pages.completed),

          active:
            here === pages.completed,

          count: 0
        }

      ]

    },


    {
      key  : 'reference',

      label: 'Reference',

      items: [

        {
          key: 'programs',

          label: 'Programs',

          icon: 'folder',

          /*
           * Programs now opens the Applicant portal's
           * Opportunities page.
           */

          url:
            '/applicant?id=opportunities',

          /*
           * Since this page belongs to the Applicant portal,
           * it will not normally be the active Reviewer Rail
           * page.
           */

          active:
            false,

          count: 0

        }

      ]

    }

  ];


  /* ============================================================
     ACTIVE PAGE FALLBACK

     A proposal detail page is reached from the queue, so it
     lights the queue rather than leaving the rail with nothing
     lit and the reader wondering where they are.
     ============================================================ */

  if (here) {

    var lit = false;


    for (
      var g = 0;
      g < data.groups.length;
      g++
    ) {

      for (
        var i2 = 0;
        i2 < data.groups[g].items.length;
        i2++
      ) {

        if (
          data.groups[g].items[i2].active
        ) {

          lit = true;

          break;

        }

      }

    }


    if (
      !lit &&
      here.indexOf('review') !== -1
    ) {

      for (
        var g2 = 0;
        g2 < data.groups.length;
        g2++
      ) {

        for (
          var i3 = 0;
          i3 < data.groups[g2].items.length;
          i3++
        ) {

          if (
            data.groups[g2].items[i3].key === 'queue'
          ) {

            data.groups[g2].items[i3].active = true;

          }

        }

      }

    }

  }


})();
